public static String addThousandSeparator(int n) {
    // Check if the number is negative
    boolean isNegative = n < 0;
    // Make the number positive
    n = Math.abs(n);
    // Initialize the result string
    String result = "";
    // Loop until the number is 0
    while (n > 0) {
        // Get the last three digits of the number
        int lastThreeDigits = n % 1000;
        // Add the last three digits to the result string
        result = lastThreeDigits + result;
        // If the number is not 0, add a dot
        if (n != 0) {
            result = "." + result;
        }
        // Divide the number by 1000
        n /= 1000;
    }
    // If the original number was negative, add a minus sign to the result
    if (isNegative) {
        result = "-" + result;
    }
    // Return the result
    return result;
}

