public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int maxArea = 0;
    int[] left = new int[n];
    int[] right = new int[n];
    Stack<Integer> stack = new Stack<>();

    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && heights[i] <= heights[stack.peek()]) {
            int top = stack.pop();
            right[top] = i;
        }
        if (!stack.isEmpty()) {
            left[i] = stack.peek();
        }
        stack.push(i);
    }

    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, heights[i] * (right[i] - left[i] - 1));
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length, n = mat[0].length, row = 0, col = 0, count = 0;
    int[] output = new int[m * n];

    while (count < m * n) {
        output[count++] = mat[row][col++];
        if (row == m - 1 && col == n) break;
        if (count < m * n) output[count++] = mat[++row][col - 1];
        if (count < m * n) output[count++] = mat[row--][--col];
        if (row == 0 && col == 0) break;
        if (count < m * n) output[count++] = mat[--row][col--];
        if (count < m * n) output[count++] = mat[row++][col++];
    }

    return output;
}

